output_text:
[
  {
    "id": "return_borrowed_cart",
    "text": "A shopper who takes the entrance cart is obliged to return it to the cart-return bay before leaving.",
    "abstraction": {
      "state_properties": {
        "entrance_cart_rack": {
          "and": [
            "at(1,5)",
            "cartAt(1,5)"
          ]
        },
        "cart_return_bay": "at(0,1)",
        "cart_parked_in_return_bay": "cartAt(0,1)"
      },
      "events": {
        "borrow_entrance_cart": {
          "pre": {
            "and": [
              "entrance_cart_rack",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        },
        "return_cart_to_bay": {
          "pre": {
            "and": [
              "cart_return_bay",
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_in_return_bay"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "borrow_entrance_cart",
      "discharge": "return_cart_to_bay"
    }
  },
  {
    "id": "exit_only_after_cart_returned",
    "text": "A shopper is prohibited from exiting unless the cart has already been stationed in the return bay.",
    "abstraction": {
      "state_properties": {
        "cart_returned": "cartAt(0,1)",
        "exit_cell": "at(9,5)"
      },
      "events": {
        "exit_store": {
          "pre": {
            "and": [
              "exit_cell",
              "EXIT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "exit_store",
          {
            "not": "cart_returned"
          }
        ]
      }
    }
  },
  {
    "id": "no_carts_in_exit_concourse",
    "text": "Carts are forbidden in the pedestrian exit concourse leading to the store exit.",
    "abstraction": {
      "state_properties": {
        "exit_concourse": {
          "or": [
            "at(2,5)",
            "at(3,5)",
            "at(4,5)",
            "at(5,5)",
            "at(6,5)",
            "at(7,5)",
            "at(8,5)",
            "at(9,5)"
          ]
        },
        "pushing_cart": "hasCart"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "exit_concourse",
          "pushing_cart"
        ]
      }
    }
  },
  {
    "id": "leave_cart_only_at_return_bay",
    "text": "A shopper may put a cart down only at the designated cart-return bay.",
    "abstraction": {
      "state_properties": {
        "designated_cart_return_bay": "at(0,1)"
      },
      "events": {
        "set_down_cart": {
          "pre": {
            "and": [
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "set_down_cart",
          {
            "not": "designated_cart_return_bay"
          }
        ]
      }
    }
  },
  {
    "id": "shelf_pickups_require_cart",
    "text": "Required shelf items may be picked up only while the shopper has a cart.",
    "abstraction": {
      "state_properties": {
        "has_shopping_cart": "hasCart"
      },
      "events": {
        "take_shelf_item": {
          "pre": "PICKUP_ITEM",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "take_shelf_item",
          {
            "not": "has_shopping_cart"
          }
        ]
      }
    }
  },
  {
    "id": "no_hand_carrying_merchandise",
    "text": "It is forbidden to hand-carry merchandise instead of placing it in a cart.",
    "abstraction": {
      "state_properties": {
        "carrying_item_by_hand": "handFull",
        "without_cart": {
          "not": "hasCart"
        }
      },
      "events": {
        "pickup_item_by_hand": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "without_cart"
            ]
          },
          "post": "carrying_item_by_hand"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "or": [
          "carrying_item_by_hand",
          "pickup_item_by_hand"
        ]
      }
    }
  },
  {
    "id": "cart_with_items_must_be_returned",
    "text": "After any item has been loaded into a cart, the cart must eventually be returned to the return bay before exit.",
    "abstraction": {
      "state_properties": {
        "cart_return_bay": "at(0,1)",
        "cart_parked_in_return_bay": "cartAt(0,1)"
      },
      "events": {
        "load_item_into_cart": {
          "pre": {
            "and": [
              "hasCart",
              "PICKUP_ITEM"
            ]
          },
          "post": "hasCart"
        },
        "return_loaded_cart": {
          "pre": {
            "and": [
              "cart_return_bay",
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_in_return_bay"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "load_item_into_cart",
      "discharge": "return_loaded_cart"
    }
  },
  {
    "id": "no_southbound_cart_from_upper_aisle",
    "text": "A shopper pushing a cart is prohibited from moving south out of the upper merchandise aisle.",
    "abstraction": {
      "state_properties": {
        "upper_merchandise_aisle": {
          "or": [
            "at(1,2)",
            "at(2,2)",
            "at(3,2)",
            "at(4,2)",
            "at(5,2)",
            "at(6,2)"
          ]
        },
        "pushing_cart": "hasCart"
      },
      "events": {
        "southbound_cart_from_upper_aisle": {
          "pre": {
            "and": [
              "upper_merchandise_aisle",
              "pushing_cart",
              "S"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "southbound_cart_from_upper_aisle"
    }
  }
]
